// Kalkulator Peluang Mini
// Ubah nilai di bawah ini:
const nA = 3; // contoh: kejadian yang diincar
const nS = 6; // contoh: semua kemungkinan

const p = nA / nS;
const percent = p * 100;

console.log('P(A) =', p);
console.log('P(A) dalam persen =', percent + '%');

// Validasi cepat
if (p < 0 || p > 1) {
  console.log('Catatan: Hasil di luar 0..1, cek kembali nA dan nS.');
} else {
  console.log('Hasil valid: 0 ≤ P(A) ≤ 1');
}

// Hitung P(A ∪ B)
// Kasus saling lepas: set pIntersec = 0
const pA = 0.8;
const pB = 0.15;
const pIntersec = 0.0; // ubah ke nilai irisan jika perlu

const pUnion = pA + pB - pIntersec;

console.log('P(A ∪ B) =', pUnion);
console.log('Dalam persen =', pUnion * 100 + '%');

// Cek cepat
if (pUnion < 0 || pUnion > 1) {
  console.log('Catatan: Hasil di luar 0..1, periksa rumus dan input.');
}
